using MegaCrit.Sts2.Core.CardSelection;
using SpireDuo.SpireDuoCode.Powers;

namespace SpireDuo.SpireDuoCode.Cards;

public sealed class SovereignPounce() : BlackCatCard(3, CardType.Attack, CardRarity.Rare, TargetType.AnyEnemy)
{ protected override IEnumerable<DynamicVar> CanonicalVars => [new DamageVar(26m, ValueProp.Move), new DynamicVar("PounceBonus", 3m)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { if (p.Target != null) await DamageCmd.Attack(DynamicVars.Damage.BaseValue).FromCard(this).Targeting(p.Target).Execute(c); } protected override void OnUpgrade() { DynamicVars.Damage.UpgradeValueBy(6m); DynamicVars["PounceBonus"].UpgradeValueBy(1m); } }
public sealed class CatwalkKing() : BlackCatCard(2, CardType.Power, CardRarity.Rare, TargetType.Self)
{ protected override IEnumerable<IHoverTip> ExtraHoverTips => [HoverTipFactory.FromPower<CatwalkKingPower>()]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) => await PowerCmd.Apply<CatwalkKingPower>(c, Owner.Creature, 1, Owner.Creature, this); protected override void OnUpgrade() => EnergyCost.UpgradeBy(-1); }
public sealed class RedRoof() : BlackCatCard(2, CardType.Attack, CardRarity.Rare, TargetType.AllEnemies)
{ protected override IEnumerable<DynamicVar> CanonicalVars => [new DamageVar(12m, ValueProp.Move)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { foreach (var e in Owner.Creature.CombatState!.HittableEnemies) { await DamageCmd.Attack(DynamicVars.Damage.BaseValue).FromCard(this).Targeting(e).Execute(c); await Owner.Creature.GetPower<FootprintStatePower>()!.RotateRight(c, this); } } protected override void OnUpgrade() => DynamicVars.Damage.UpgradeValueBy(3m); }
public sealed class PerfectArc() : BlackCatCard(1, CardType.Attack, CardRarity.Rare, TargetType.AnyEnemy)
{ protected override IEnumerable<DynamicVar> CanonicalVars => [new DamageVar(10m, ValueProp.Move)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { if (p.Target == null) return; await DamageCmd.Attack(DynamicVars.Damage.BaseValue).FromCard(this).Targeting(p.Target).Execute(c); var s = Owner.Creature.GetPower<FootprintStatePower>(); if (s?.HasTriggered(FootprintLine.Pounce) == true) await DamageCmd.Attack(8).FromCard(this).Targeting(p.Target).Execute(c); } protected override void OnUpgrade() => DynamicVars.Damage.UpgradeValueBy(3m); }
