{ protected override IEnumerable<IHoverTip> ExtraHoverTips => [HoverTipFactory.FromPower<FelineVelocityPower>()]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) => await PowerCmd.Apply<FelineVelocityPower>(c, Owner.Creature, IsUpgraded ? 2 : 3, Owner.Creature, this); protected override void OnUpgrade() { } }
public sealed class NeedleLeap() : BlackCatCard(0, CardType.Attack, CardRarity.Rare, TargetType.AnyEnemy)
{ public override IEnumerable<CardKeyword> CanonicalKeywords => [CardKeyword.Exhaust]; protected override IEnumerable<DynamicVar> CanonicalVars => [new DamageVar(4m, ValueProp.Move), new RepeatVar(3)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { if (p.Target != null) await DamageCmd.Attack(DynamicVars.Damage.BaseValue).WithHitCount(3).FromCard(this).Targeting(p.Target).Execute(c); } protected override void OnUpgrade() => DynamicVars.Damage.UpgradeValueBy(1m); }
public sealed class ImmaculateCoat() : BlackCatCard(2, CardType.Power, CardRarity.Rare, TargetType.Self)
{ protected override IEnumerable<DynamicVar> CanonicalVars => [new PowerVar<ImmaculateCoatPower>(5m)]; protected override IEnumerable<IHoverTip> ExtraHoverTips => [HoverTipFactory.FromPower<ImmaculateCoatPower>()]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) => await PowerCmd.Apply<ImmaculateCoatPower>(c, Owner.Creature, DynamicVars["ImmaculateCoatPower"].BaseValue, Owner.Creature, this); protected override void OnUpgrade() => DynamicVars["ImmaculateCoatPower"].UpgradeValueBy(2m); }
public sealed class GrandGrooming() : BlackCatCard(2, CardType.Skill, CardRarity.Rare, TargetType.Self)
{ public override bool GainsBlock => true; protected override IEnumerable<DynamicVar> CanonicalVars => [new BlockVar(18m, ValueProp.Move)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { await CreatureCmd.GainBlock(Owner.Creature, DynamicVars.Block, p); var s = await FootprintStatePower.GetOrCreate(c, Owner.Creature, this); for (int i = 0; i < 3; i++) if (s.Slots[i] == Footprint.Empty && !s.Locked[i]) await s.Set(c, i, Footprint.Skill, this); } protected override void OnUpgrade() => DynamicVars.Block.UpgradeValueBy(6m); }
public sealed class PurrfectOrder() : BlackCatCard(2, CardType.Power, CardRarity.Rare, TargetType.Self)
{ protected override IEnumerable<DynamicVar> CanonicalVars => [new PowerVar<PurrfectOrderPower>(6m)]; protected override IEnumerable<IHoverTip> ExtraHoverTips => [HoverTipFactory.FromPower<PurrfectOrderPower>()]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) => await PowerCmd.Apply<PurrfectOrderPower>(c, Owner.Creature, DynamicVars["PurrfectOrderPower"].BaseValue, Owner.Creature, this); protected override void OnUpgrade() => DynamicVars["PurrfectOrderPower"].UpgradeValueBy(3m); }
public sealed class SilentHousehold() : BlackCatCard(1, CardType.Skill, CardRarity.Rare, TargetType.Self)
{ public override bool GainsBlock => true; protected override IEnumerable<DynamicVar> CanonicalVars => [new BlockVar(7m, ValueProp.Move)]; protected override async Task OnPlay(PlayerChoiceContext c, CardPlay p) { var selected = await CardSelectCmd.FromHand(c, Owner, new CardSelectorPrefs(SelectionScreenPrompt, 0), x => x != this, this); foreach (var card in selected) { await CardCmd.Exhaust(c, card); await CreatureCmd.GainBlock(Owner.Creature, DynamicVars.Block, p); } } protected override void OnUpgrade() => DynamicVars.Block.UpgradeValueBy(2m); }
